mapper.select:
select SEQNO,busiDate,startTime,endTime,status,detailAction,taskCname,lastTime,orderno from ( SELECT LOG.SEQNO,to_char(LOG.BUSI_DATE,'yyyyMMdd') busiDate,LOG.START_TIME startTime,LOG.END_TIME endTime ,DECODE(LOG.STATUS,'02',DECODE(nvl(logDetail.ERROR,0),0,'02','09'),LOG.STATUS) status ,DECODE(LOG.STATUS,'02',DECODE(nvl(logDetail.ERROR,0),0,'执行成功'||nvl(logDetail.success,0)||'条','执行成功'||nvl(logDetail.success,0)||'条,失败'||nvl(logDetail.ERROR,0)||'条'),LOG.DETAIL_ACTION) detailAction ,GR.TASK_GRP_NAME taskCname,ROUND(LOG.LAST_TIME/1000,2) lastTime,GR.orderno FROM VAL_INTERF_ACTIONLOG LOG left join ( SELECT TASK_GRP_ID, TASK_GRP_NAME,ORDER_NO orderno FROM bok_BATCH_TASK_GRP GROUP BY TASK_GRP_ID, TASK_GRP_NAME,ORDER_NO ) GR on GR.TASK_GRP_ID = to_char(LOG.ORDERNO) LEFT JOIN( SELECT a.parent_seqno,sum(a.success) success,sum(a.ERROR) ERROR FROM ( SELECT parent_seqno parent_seqno, DECODE(VAL.IS_CHECK,'Y',LENGHT) success,DECODE(VAL.IS_CHECK,'N',LENGHT) ERROR from ( SELECT parent_seqno,IS_CHECK,COUNT(1) LENGHT FROM VAL_INTERFLOG WHERE 1=1 group by parent_seqno,IS_CHECK) val) a group by parent_seqno
) logDetail ON LOG.Seqno=logDetail.parent_seqno WHERE 1=1
AND LOG.EXECTASK_SEQNO = #{execTaskId} ) logdetail WHERE 1=1
AND logdetail.status = #{status}
ORDER BY busiDate,logdetail.orderno

select l.file_name,l.ex_date,l.num,l.is_check,l.detail,l.remark 
	from val_interflog l
	where l.TMP_NAME = #{tmpName}
	AND l.parent_seqno = #{parentSeqno}


		AND l.IS_CHECK = #{logStatus}
